INSERT INTO sources (slug, kind, label, url, checked_date, access) VALUES ('src-new-crops-2026-11-18', 'research', 'New cut-flower crops enumeration, Nov 2026 — variety names and plain growing facts from specialist seed catalogues and extension references; names and facts only, no text or photos reproduced.', NULL, '2026-11-18', 'public');
INSERT INTO plants (slug, common_name, latin_name, description, sowing_notes, category_id, updated_seq, season_class, season_source_id, sowing_method_source_id, life_cycle, hardiness, grower_guide, grower_guide_source_id) VALUES ('echinacea', 'Echinacea (Coneflower)', 'Echinacea purpurea / E. angustifolia', NULL, NULL, 1, 1453, NULL, NULL, (SELECT id FROM sources WHERE slug = 'src-new-crops-2026-11-18'), 'Perennial', 'Perennial in Zones 3–8.', '{"growing": {"sowing": "Start indoors in late winter, or sow outside in fall and let winter do the chilling for you. A stretch of cold, damp conditions in the fridge — 8 to 12 weeks — improves sprouting for spring sowing.", "germination": "Seed sprouts in 10 to 21 days at about 65–72°F. Sow ⅛ to ¼ inch deep.", "transplanting": "Start indoors 8 to 10 weeks before you want to plant out. Move plants outside after frost, once the soil has warmed.", "days_to_bloom": "Expect flowers in the second year — echinacea spends its first year building a strong root and crown.", "spacing": "Space plants 12 to 18 inches apart.", "growing": "Full sun, at least 6 hours a day, and soil that drains well. Once settled in, it handles drought well, and it sows itself freely.", "good_to_know": ["Leave the standing seed heads for the goldfinches — they love them — and expect seedlings to pop up around the parent plants."]}, "seedSaving": {"when_to_harvest": "Let the cones dry on the plant until they are dark brown to black, crisp, and prickly. Rub a cone with a gloved thumb — ripe seed loosens and starts to come away.", "how_to_collect": "Cut the dry cones into a paper bag before they shatter and drop their seed. Rub the cones hard between your palms, or shake the heads in a lidded can, to knock the seed free.", "cleaning": "The seed is heavier than the chaff, so blow across it, or pour it in front of a fan, and the light bits lift away. Pick out any soft or pale seed.", "drying": "If the cones feel at all damp, spread or hang them in a dry, airy place for 2 to 3 weeks to finish drying before you rub the seed out.", "storage": "Store in a sealed jar in a cool, dark, dry place. In good storage it stays viable about 2 to 3 years.", "pollination_notes": "The common garden species are open-pollinated and come true when grown on their own, but the species cross with each other and hybrids pop up — grow one kind by itself for true seed.", "difficulty": "moderate"}}', (SELECT id FROM sources WHERE slug = 'src-seed-saving-grower-notes'));
